schema.content:
Table "actors" {
  "actorid" INTEGER [pk, not null]
  "a_gender" TEXT [not null]
  "a_quality" INTEGER [not null]
}

Table "directors" {
  "directorid" INTEGER [pk, not null]
  "d_quality" INTEGER [not null]
  "avg_revenue" INTEGER [not null]
}

Table "movies" {
  "movieid" INTEGER [pk, not null]
  "year" INTEGER [not null]
  "isEnglish" TEXT [not null]
  "country" TEXT [not null]
  "runningtime" INTEGER [not null]
}

Table "movies2actors" {
  "movieid" INTEGER [pk, not null]
  "actorid" INTEGER [pk, not null]
  "cast_num" INTEGER [not null]
}

Table "movies2directors" {
  "movieid" INTEGER [pk, not null]
  "directorid" INTEGER [pk, not null]
  "genre" TEXT [not null]
}

Table "u2base" {
  "userid" INTEGER [pk, not null]
  "movieid" INTEGER [pk, not null]
  "rating" TEXT [not null]
}

Table "users" {
  "userid" INTEGER [pk, not null]
  "age" TEXT [not null]
  "u_gender" TEXT [not null]
  "occupation" TEXT [not null]
}
